-- =========================================================================
-- Pabitra Lenka Portfolio - Supabase Database Schema & Setup Script
-- =========================================================================
-- Instructions:
-- 1. Create a free project at https://supabase.com
-- 2. Open the Supabase Dashboard -> "SQL Editor"
-- 3. Click "New Query", paste this entire script, and click "RUN"
-- 4. Go to Project Settings -> API, copy your "Project URL" and "anon public key"
-- 5. Open your portfolio's /admin/ page -> "Supabase Database" tab, paste and save!
-- =========================================================================

-- 1. Create the unified portfolio_store table (Fastest & most flexible)
create table if not exists public.portfolio_store (
  key text primary key,
  data jsonb not null,
  updated_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 2. Enable Row Level Security (RLS)
alter table public.portfolio_store enable row level security;

-- 3. Create RLS Policies
-- Allow anyone to read portfolio data (so your public website can load live data)
drop policy if exists "Allow public read portfolio_store" on public.portfolio_store;
create policy "Allow public read portfolio_store"
  on public.portfolio_store
  for select
  using (true);

-- Allow anonymous or authenticated write (managed via the /admin/ passcode gate)
drop policy if exists "Allow anon write portfolio_store" on public.portfolio_store;
create policy "Allow anon write portfolio_store"
  on public.portfolio_store
  for all
  using (true)
  with check (true);

-- 4. Pre-populate Seed Data (Inserts default portfolio contents)
insert into public.portfolio_store (key, data, updated_at) values
